40\\u0435\\u0431\\u0443\\u044e\\u0442 \\u044f\\u0432\\u043d\\u043e\\u0439 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 |\\n| Warmup / timing window | 10 warmup steps (\\u043e\\u0442\\u0431\\u0440\\u0430\\u0441\\u044b\\u0432\\u0430\\u0435\\u043c), 100 timed steps; \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0430 \\u043f\\u043e 3 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430\\u043c (seeds) | \\u0421\\u0442\\u0430\\u0431\\u0438\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 |\\n| Tensor parallel TP | =1 \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435; \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e TP=2 \\u0432 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435 sensitivity | \\u041d\\u0435 \\u043f\\u0443\\u0442\\u0430\\u0442\\u044c PP-bubble \\u0441 TP-overhead |\\n| 1F1B-I (interleaved) virtual stages v | =2 (\\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442 \\u00abPipeDream-flush\\u00bb \\u0441 v=2); \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e v=4 \\u043a\\u0430\\u043a sensitivity | Interleaved, \\u0434\\u0430\\u0451\\u0442 v\\u20131\\u00d7 \\u043c\\u0435\\u043d\\u044c\\u0448\\u0435 bubble \\u043f\\u043e \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0435 (P\\u20131)/(M+P\\u20131) |\\n| torch.compile / cuda-graphs | OFF | \\u0418\\u043d\\u0430\\u0447\\u0435 kernel-fusing \\u043c\\u0430\\u0441\\u043a\\u0438\\u0440\\u0443\\u0435\\u0442 bubble |\\n\\n#### 2.2. \\u041f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435 (\\u0442\\u043e, \\u0447\\u0442\\u043e \\u0432\\u0430\\u0440\\u044c\\u0438\\u0440\\u0443\\u0435\\u043c)\\n\\n\\u0413\\u043b\\u0430\\u0432\\u043d\\u0430\\u044f \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f: **M \\u2208 {8, 16, 32, 64, 128, 256}** \\u043f\\u0440\\u0438 G=512.\\n\\nSecondary (sensitivity, \\u043d\\u0435 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u0441\\u0435\\u0442\\u043a\\u0430):\\n- P_s \\u2208 {4, 8, 16}\\n- v \\u2208 {2, 4} \\u0434\\u043b\\u044f 1F1B-I\\n- AC on/off (\\u0434\\u043b\\u044f ZB-H2)\\n- N=8 \\u043a\\u0430\\u043a sanity (P_s \\u043d\\u0435 \\u043c\\u0435\\u043d\\u044f\\u0435\\u043c, \\u043d\\u043e \\u043f\\u0435\\u0440\\u0435\\u0441\\u0447\\u0438\\u0442\\u044b\\u0432\\u0430\\u0435\\u043c DP, \\u0447\\u0442\\u043e\\u0431\\u044b \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u044b \\u00b5 \\u043e\\u0441\\u0442\\u0430\\u0432\\u0430\\u043b\\u0438\\u0441\\u044c \\u0432\\u0430\\u043b\\u0438\\u0434\\u043d\\u044b\\u043c\\u0438)\\n\\n\\u0412\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043a\\u0438 \\u043f\\u0435\\u0440\\u0435\\u0431\\u0438\\u0440\\u0430\\u0435\\u043c 4 \\u0440\\u0430\\u0441\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u044f: **1F1B, 1F1B-I (v=2), ZB-1p, ZB-2p** + \\u0434\\u0432\\u0430 sanity: GPipe, PipeDream-Async.\\n\\n#### 2.3. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438\\n\\n1. **Throughput T** \\u2014 samples/sec (\\u0438\\u043b\\u0438 tokens/sec), \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0430 \\u043f\\u043e timed-step \\u043e\\u043a\\u043d\\u0443.\\n2. **Bubble fraction B** \\u2014 \\u0434\\u0432\\u0443\\u043c\\u044f \\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u0430\\u043c\\u0438:\\n   - wall-bubble: (\\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435_step \\u2212 \\u0447\\u0438\\u0441\\u0442\\u044b\\u0439_compute_step)/\\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435_step \\u0438\\u0437 `nsys`/`torch.profiler`;\\n   - FLOPs-bubble: (\\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435_\\u0432\\u0440\\u0435\\u043c\\u044f_\\u043f\\u043e_FLOPs \\u2212 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0430\\u0435\\u043c\\u043e\\u0435)/\\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435, \\u043a\\u0430\\u043a sanity.\\n3. **Time-to-train** \\u2014 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e tokens (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, 1B) \\u2192 \\u0441\\u0435\\u043a\\u0443\\u043d\\u0434\\u044b.\\n4. **Peak memory** \\u2014 max resident set GPU-0; \\u0432\\u0430\\u0436\\u043d\\u043e \\u0434\\u043b\\u044f ZB-H1/H2 (\\u0433\\u0434\\u0435 f/b/w \\u0440\\u0430\\u0437\\u043d\\u0435\\u0441\\u0435\\u043d\\u044b).\\n5. **Communication fraction** \\u2014 % step time \\u043f\\u043e\\u0434 NCCL (\\u0438\\u0437 `nsys`).\\n6. **T_upper** \\u2014 \\u0442\\u0435\\u043e\\u0440\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043e\\u0442\\u043e\\u043b\\u043e\\u043a T_upper = N\\u00b7\\u00b5\\u00b7F_compute / step_time_no_bubble_no_comm; \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 T/T_upper.\\n7. **|T_\\u0442\\u0435\\u043e\\u0440 \\u2212 T_obs|** \\u2014 \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0430\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 bubble vs \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0439; \\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u044f \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b.\\n\\n#### 2.4. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f (baselines / sanity)\\n\\n- **GPipe** \\u2014 bubble = (P_s\\u22121)/(M+P_s\\u22121); sanity, \\u0447\\u0442\\u043e \\u043c\\u044b \\u0432\\u0438\\u0434\\u0438\\u043c \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u0443\\u044e bubble-\\u043a\\u0440\\u0438\\u0432\\u0443\\u044e.\\n- **PipeDream-Async** \\u2014 sanity, \\u0447\\u0442\\u043e schedule \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f; throughput \\u043d\\u0435 \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d \\u0431\\u044b\\u0442\\u044c best-of-4.\\n- **\\u041e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u0447\\u0435\\u0442\\u0432\\u0451\\u0440\\u043a\\u0430**: 1F1B, 1F1B-I, ZB-1p, ZB-2p \\u2014 \\u0442\\u043e, \\u043f\\u043e \\u0447\\u0435\\u043c\\u0443 \\u043e\\u0442\\u0432\\u0435\\u0447\\u0430\\u0435\\u043c \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441.\\n- **\\u0412\\u043d\\u0443\\u0442\\u0440\\u0435\\u043d\\u043d\\u0438\\u0439 \\u00ab\\u0442\\u0435\\u043e\\u0440\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439\\u00bb baseline**: T_upper; \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 throughput T/T_upper.\\n\\n#### 2.5. \\u041f\\u043b\\u0430\\u043d \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043e\\u0432 \\u0438 seeds\\n\\n- 3 seed'\\u0430 {0,1,2} \\u0434\\u043b\\u044f \\u0438\\u043d\\u0438\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430 data-loader + tie-breaking \\u0432 ZB-2p.\\n- \\u0412 \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c seed'\\u0435 \\u0431\\u0435\\u0440\\u0451\\u043c **\\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0443** throughput \\u043f\\u043e 100 timed steps; warmup 10 \\u0448\\u0430\\u0433\\u043e\\u0432 \\u043e\\u0442\\u0431\\u0440\\u0430\\u0441\\u044b\\u0432\\u0430\\u0435\\u043c.\\n- \\u0418\\u043d\\u0442\\u0435\\u0440\\u0432\\u0430\\u043b\\u044b \\u2014 IQR (25..75 \\u043f\\u0435\\u0440\\u0446\\u0435\\u043d\\u0442\\u0438\\u043b\\u0438) \\u043f\\u043e 3 seed'\\u0430\\u043c, \\u043d\\u0435 std.\\n- \\u041e\\u0431\\u044a\\u0451\\u043c: |M-grid|\\u00b7|methods|\\u00b7|P_s grid|\\u00b7|AC opt|\\u00b73 seeds \\u2248 6\\u00b76\\u00b73\\u00b72\\u00b73 \\u2248 **648 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432**; \\u22483 \\u043c\\u0438\\u043d/\\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u21d2 \\u224832 GPU-\\u0447\\u0430\\u0441\\u043e\\u0432 \\u043d\\u0430 16 GPU \\u2014 \\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u043e \\u0434\\u043b\\u044f \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e A100-\\u0443\\u0437\\u043b\\u0430.\\n\\n#### 2.6. \\u0413\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u044b (\\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438, \\u043d\\u0435 \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u0438\\u044f)\\n\\n- **H1:** T(1F1B) \\u2014 \\u0432\\u043e\\u0437\\u0440\\u0430\\u0441\\u0442\\u0430\\u044e\\u0449\\u0430\\u044f \\u0432\\u043e\\u0433\\u043d\\u0443\\u0442\\u0430\\u044f \\u0444\\u0443\\u043d\\u043a\\u0446\\u0438\\u044f M \\u0441 \\u043d\\u0430\\u0441\\u044b\\u0449\\u0435\\u043d\\u0438\\u0435\\u043c ~M \\u2248 2\\u00b7P_s = 16. Bubble \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0430 (P\\u20131)/(M+P\\u20131).\\n- **H2:** T(1F1B-I, v=2) \\u2014 \\u0442\\u043e \\u0436\\u0435 \\u043f\\u043e\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u0435, asymptotic ceiling \\u0432\\u044b\\u0448\\u0435 \\u2248 \\u0432 v \\u0440\\u0430\\u0437 \\u043f\\u043e bubble.\\n- **H3:** T(ZB-1p) \\u2014 \\u0444\\u043e\\u0440\\u043c\\u0430 \\u043a\\u0430\\u043a \\u0443 1F1B, \\u043d\\u0430\\u0441\\u044b\\u0449\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0430\\u043d\\u044c\\u0448\\u0435; bubble \\u2248 (P\\u22121)/(M+P\\u22121).\\n- **H4:** T(ZB-2p) \\u2014 \\u043f\\u043e\\u0447\\u0442\\u0438 flat \\u043f\\u043e M \\u043d\\u0430\\u0447\\u0438\\u043d\\u0430\\u044f \\u0441 M \\u2248 P_s/2; bubble \\u2248 O(2/M) \\u0438\\u043b\\u0438 \\u043c\\u0435\\u043d\\u044c\\u0448\\u0435, W-\\u043f\\u0443\\u0437\\u044b\\u0440\\u044c \\u0441\\u0445\\u043e\\u0434\\u0438\\u0442.\\n- **H5:** GPipe \\u2014 \\u043f\\u0440\\u043e\\u0438\\u0433\\u0440\\u044b\\u0432\\u0430\\u0435\\u0442 \\u0432\\u0441\\u0435\\u043c 4 \\u0440\\u0430\\u0441\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u044f\\u043c \\u043f\\u043e bubble fraction.\\n\\nPass/fail-\\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0438 (default; \\u043f\\u043e\\u0434\\u0432\\u0438\\u043d\\u0443 \\u043f\\u043e \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u0443):\\n- T(1F1B, M=256) / T(1F1B, M=8) **> 1.5\\u00d7** \\u2014 \\u00ab\\u044f\\u0432\\u043d\\u044b\\u0439 \\u0440\\u043e\\u0441\\u0442\\u00bb;\\n- T(1F1B-I, M=256) / T(1F1B-I, M=8) **> 1.5\\u00d7**;\\n- T(ZB-1p, M=256) / T(ZB-1p, M=8) **> 1.3\\u00d7**;\\n- T(ZB-2p, M=128) / T(ZB-2p, M=8) **< 1.2\\u00d7** (flat);\\n- T(ZB-2p, M=8) **\\u2265** T(1F1B, M=128) \\u2014 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e: ZB-2p \\u0441 \\u043c\\u0430\\u043b\\u044b\\u043c M \\u0434\\u043e\\u0433\\u043e\\u043d\\u044f\\u0435\\u0442 1F1B \\u0441 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043c M.\\n\\n---\\n\\n### 3. \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438\\n\\n#### 3.1. \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f (assumptions)\\n\\n1. ZB-2p \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d \\u0432 `Megatron-LM`/`ZeroBubble` \\u0442\\u0430\\u043a, \\u0447\\u0442\\u043e \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432\\u043e\\u043f\\u043e\\u043b\\u043e\\u0436\\u043d\\u044b\\u0435 W \\u043d\\u0435 \\u043a\\u043e\\u043d\\u0444\\u043b\\u0438\\u043a\\u0442\\u0443\\u044e\\u0442 \\u043f\\u043e bandwidth \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043e\\u0434\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0434\\u0438\\u0438; \\u0435\\u0441\\u043b\\u0438 \\u044d\\u0442\\u043e \\u043d\\u0435 \\u0442\\u0430\\u043a \\u2014 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c \\u044f\\u0432\\u043d\\u044b\\u0439 NCCL-overlap \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433.\\n2. AC \\u0432\\u044b\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435; ZB-H1/H2 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 satellite-\\u0441\\u0435\\u0442\\u043a\\u0435.\\n3. PP \\u0432 \\u0441\\u0442\\u0438\\u043b\\u0435 GPipe: \\u0441\\u0442\\u0430\\u0434\\u0438\\u0438 \\u2014 \\u044d\\u0442\\u043e \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0441\\u043b\\u043e\\u0438, \\u0431\\u0435\\u0437 branching.\\n4. N=16, P_s=8: \\u00ab1 GPU = 1 \\u0441\\u0442\\u0430\\u0434\\u0438\\u044f\\u00bb, \\u0431\\u0435\\u0437 PP\\u00d7DP-shard overlap'a.\\n5. BF16 fwd/bwd, FP32 master; all-reduce grads = fwd\\u00b7|W|\\u00b72 \\u0431\\u0430\\u0439\\u0442\\u0430/\\u043f\\u0430\\u0440\\u0430\\u043c/\\u0441\\u0442\\u0430\\u0434\\u0438\\u044f.\\n6. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u043a\\u0430: B_1F1B \\u2248 (P\\u22121)/(M+P\\u22121); B_1F1B-I(v) \\u2248 (P\\u22121)/(v\\u00b7(M+P\\u22121)); B_ZB-2p \\u2248 2/P \\u043f\\u0440\\u0438 \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u0445 M.\\n7. ZB-2p \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d \\u0434\\u043b\\u044f \\u0447\\u0451\\u0442\\u043d\\u043e\\u0433\\u043e P \\u2192 \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435 P=8,16; \\u043d\\u0435\\u0447\\u0451\\u0442\\u043d\\u044b\\u0439 P \\u2014 out of scope.\\n8. torch.compile/cuda-graphs \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u044b.\\n9. Seed \\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 dataloader + init; bubble fraction \\u043e\\u0442 seed \\u043d\\u0435 \\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u0442.\\n\\n#### 3.2. \\u041d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 (uncertainties)\\n\\n1. **\\u0410\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u043a\\u0430 ZB-2p** \\u2014 \\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0430\\u044f; \\u0442\\u043e\\u0447\\u043d\\u044b\\u0435 \\u043a\\u043e\\u044d\\u0444\\u0444\\u0438\\u0446\\u0438\\u0435\\u043d\\u0442\\u044b \\u0437\\u0430\\u0432\\u0438\\u0441\\u044f\\u0442 \\u043e\\u0442 F/B/W ratio \\u0438 \\u0431\\u0435\\u0437 \\u0441\\u0438\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u0430 \\u043d\\u0435 \\u043e\\u0447\\u0435\\u0432\\u0438\\u0434\\u043d\\u044b \\u2192 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u0435\\u043c \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u044b\\u0439 vs \\u0430\\u043d\\u0430\\u043b\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 bubble; \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 >15% \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0440\\u0435\\u0432\\u0438\\u0437\\u0438\\u0438 \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u044b.\\n2. **ZB-2p \\u043f\\u0440\\u0438 \\u043d\\u0435\\u0447\\u0451\\u0442\\u043d\\u043e\\u043c P** \\u2014 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u044b\\u0439 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441; \\u043d\\u0435 \\u043f\\u043e\\u043a\\u0440\\u044b\\u0432\\u0430\\u0435\\u043c.\\n3. **Comm-bound \\u0440\\u0438\\u0441\\u043a** \\u2014 NCCL all-reduce/all-gather/reduce-scatter \\u0432 backward \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0441\\u044a\\u0435\\u0441\\u0442\\u044c free bubble ZB-2p \\u043f\\u0440\\u0438 \\u043c\\u0430\\u043b\\u044b\\u0445 M.\\n4. **BF16 recompute vs FP16 grad-accum** \\u2014 \\u0434\\u0435\\u0442\\u0430\\u043b\\u0438 grad scaling \\u043c\\u043e\\u0433\\u0443\\u0442 \\u0438\\u0441\\u043a\\u0430\\u0437\\u0438\\u0442\\u044c throughput.\\n5. **\\u041e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 bubble fraction** \\u2014 wall-bubble vs FLOPs-bubble \\u0434\\u0430\\u044e\\u0442 \\u0440\\u0430\\u0437\\u043d\\u044b\\u0435 \\u0447\\u0438\\u0441\\u043b\\u0430, \\u0435\\u0441\\u043b\\u0438 \\u043a\\u043e\\u043c\\u043c\\u0443\\u043d\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 \\u043d\\u0435 \\u0441\\u043a\\u0440\\u044b\\u0442\\u044b; primary \\u0431\\u0435\\u0440\\u0451\\u043c wall-bubble.\\n6. **\\u041c\\u0430\\u0448\\u0438\\u043d\\u043d\\u044b\\u0439 jitter** \\u2014 step time \\u226410 \\u043c\\u0441 \\u043f\\u0440\\u0438 G=512,M=8; \\u0434\\u0436\\u0438\\u0442\\u0447 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0434\\u043e\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u2192 \\u043c\\u0438\\u043d\\u0438\\u043c\\u0443\\u043c M\\u22658 \\u0438 \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u0430 \\u043f\\u043e 100 \\u0448\\u0430\\u0433\\u043e\\u0432.\\n7. **\\u0411\\u0430\\u043b\\u0430\\u043d\\u0441\\u0438\\u0440\\u043e\\u0432\\u043a\\u0430 vocab/seq** \\u2014 LM-head \\u043d\\u0430 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043d\\u0435\\u0439 \\u0441\\u0442\\u0430\\u0434\\u0438\\u0438 \\u043d\\u0430\\u0440\\u0443\\u0448\\u0430\\u0435\\u0442 \\u0431\\u0430\\u043b\\u0430\\u043d\\u0441; \\u0441\\u0442\\u0440\\u0430\\u0442\\u0435\\u0433\\u0438\\u044f: \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u043e\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e transformer-\\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u043d\\u0430 \\u0441\\u0442\\u0430\\u0434\\u0438\\u044e, embedding \\u043d\\u0430 \\u0441\\u0442\\u0430\\u0434\\u0438\\u044e 0, LM-head \\u043d\\u0430 P\\u20131.\\n8. **W-\\u0444\\u0430\\u0437\\u0430 warmup** \\u2014 ZB-2p \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 P_s \\u0448\\u0430\\u0433\\u043e\\u0432 warmup; \\u0447\\u0430\\u0441\\u0442\\u044c microbatches \\u0443\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0432 pipeline-fill \\u2192 \\u0431\\u0435\\u0440\\u0451\\u043c steady-state, \\u043e\\u0442\\u0431\\u0440\\u0430\\u0441\\u044b\\u0432\\u0430\\u0435\\u043c fill+drain.\\n9. **Wall vs FLOPs bubble** \\u2014 \\u043a\\u0430\\u043a\\u043e\\u0439 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0441\\u0440\\u0435\\u0437 `nsys` \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u044c \\u043a\\u0430\\u043a \\u00ab\\u0438\\u0434\\u0435\\u0430\\u043b\\u00bb \\u21d2 \\u043d\\u0443\\u0436\\u0435\\u043d pre-pass \\u0441 \\u0441\\u0438\\u043c\\u0443\\u043b\\u044f\\u0442\\u043e\\u0440\\u043e\\u043c \\u0440\\u0430\\u0441\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0439 \\u0434\\u043e \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430.\\n10. **1F1B-I(v>2) memory trade-off** \\u2014 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u0442\\u044c AC, \\u0438\\u043d\\u0430\\u0447\\u0435 out-of-memory; \\u043e\\u0442\\u043c\\u0435\\u0442\\u0438\\u0442\\u044c \\u043a\\u0430\\u043a caveat.\\n\\n---\\n\\n### \\u0417\\u0430\\u043f\\u0440\\u043e\\u0441 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u043e\\u0442 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f\\n\\n\\u041f\\u0440\\u0435\\u0436\\u0434\\u0435 \\u0447\\u0435\\u043c \\u043f\\u0435\\u0440\\u0435\\u0445\\u043e\\u0434\\u0438\\u0442\\u044c \\u043a stage=result, \\u043f\\u0440\\u043e\\u0448\\u0443 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0438\\u0442\\u044c:\\n\\n1. M-\\u0441\\u0435\\u0442\\u043a\\u0430 {8..256} \\u043f\\u0440\\u0438 G=512 \\u2014 \\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u0442\\u044c \\u0438\\u043b\\u0438 \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u0438\\u0442\\u044c \\u0434\\u043e {4..512}?\\n2. P_s=8 \\u043a\\u0430\\u043a primary \\u2014 \\u0438\\u043b\\u0438 \\u0432\\u0437\\u044f\\u0442\\u044c P_s=16 \\u0434\\u043b\\u044f \\u0431\\u043e\\u043b\\u0435\\u0435 \\u0432\\u044b\\u0440\\u0430\\u0436\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e bubble 1F1B?\\n3. AC off \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435, AC on \\u2014 sensitivity?\\n4. \\u041f\\u043e\\u0440\\u043e\\u0433\\u0438 pass/fail \\u0432 \\u043f.2.7 (1.5\\u00d7 / 1.3\\u00d7 / 1.2\\u00